      // T wave (broader bump at ~60%)
      else if (t >= 0.52 && t < 0.68) {
        y = 0.25 * Math.sin((t - 0.52) * Math.PI / 0.16);
      }

      // Add subtle noise
      y += (Math.random() - 0.5) * 0.03;

      // Scale amplitude slightly by HR deviation from normal
      const hrScale = 0.8 + 0.4 * ((hr || 72) / 80);
      y *= hrScale;
