        idx: baseTime + i,
        value: parseFloat(y.toFixed(3)),
        time: `${(beatIdx * beatInterval + i / samplesPerBeat * beatInterval).toFixed(1)}s`
      });
    }
  });

  // Keep last 300 points for display
  return ecgPoints.slice(-300);
}

